INSERT OR IGNORE INTO content_items (id, type, slug, status, sort_order, cover_media_id, meta_json, version, current_published_revision_id, created_at, updated_at, deleted_at) VALUES ('seed_post_sme_website_cost_estimate', 'post', 'sme-website-cost-estimate', 'published', 100, 'seed_media_blog_multilingual_product_system', '{"series":"service-guides","surface":"blog","status":"live","featured":true,"intent":"website-cost","coverAltVi":"Bản đồ phạm vi và nội dung khi lập ngân sách website SME","coverAltEn":"Scope and content map for an SME website estimate","coverAltJa":"中小企業サイトの見積もりに必要な範囲とコンテンツの整理","coverAltZh":"中小企业网站估算中的范围与内容地图"}', 1, 'seed_post_sme_website_cost_estimate_r1', '2026-07-29T00:00:00.000Z', '2026-07-29T00:00:00.000Z', NULL);
INSERT OR IGNORE INTO revisions (id, content_item_id, version, status, data_json, created_by, created_at, published_at, slug, sort_order, cover_media_id) SELECT 'seed_post_sme_website_cost_estimate_r1', 'seed_post_sme_website_cost_estimate', 1, 'published', '{"series":"service-guides","surface":"blog","status":"live","featured":true,"intent":"website-cost","coverAltVi":"Bản đồ phạm vi và nội dung khi lập ngân sách website SME","coverAltEn":"Scope and content map for an SME website estimate","coverAltJa":"中小企業サイトの見積もりに必要な範囲とコンテンツの整理","coverAltZh":"中小企业网站估算中的范围与内容地图"}', 'seed:buyer-intent:2026-07-29:v1', '2026-07-29T00:00:00.000Z', '2026-07-29T00:00:00.000Z', 'sme-website-cost-estimate', 100, 'seed_media_blog_multilingual_product_system' WHERE EXISTS (SELECT 1 FROM content_items WHERE id = 'seed_post_sme_website_cost_estimate');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_sme_website_cost_estimate_r1', 'vi', '{"title":"Chi phí website SME được quyết định bởi phạm vi, không phải số trang","eyebrow":"Website cho SME","excerpt":"Một báo giá website rõ ràng không bắt đầu bằng một con số cố định cho mỗi trang. Nó bắt đầu từ mục tiêu kinh doanh, nội dung cần chuẩn bị, mức độ quản trị và những tích hợp thật sự phải vận hành.","seoTitle":"Chi phí website SME: những yếu tố quyết định báo giá — TUNG","seoDescription":"Hiểu cách ước tính chi phí website cho doanh nghiệp vừa và nhỏ: phạm vi, nội dung, CMS, tích hợp, SEO và bàn giao.","body":[{"type":"heading","text":"Báo giá tốt là một mô hình phạm vi"},{"type":"paragraph","text":"Một website doanh nghiệp không được định giá công bằng chỉ bằng số lượng trang. Hai website cùng có mười trang có thể khác nhau rất xa nếu một bên chỉ cần nội dung tĩnh và form liên hệ, còn bên kia cần CMS, đa ngôn ngữ, phân quyền, tích hợp CRM hoặc quy trình nhận và xử lý lead. Vì vậy, một báo giá đáng tin nên giải thích những quyết định nào tạo ra công sức và rủi ro, thay vì chỉ đưa ra một con số khiến hai bên phải đoán."},{"type":"heading","text":"Năm yếu tố thường làm thay đổi ước tính"},{"type":"list","items":["Mục tiêu và cấu trúc nội dung: website giới thiệu, tuyển lead, bán hàng hay hỗ trợ một quy trình vận hành.","Mức độ sẵn sàng của nội dung: đã có thông điệp, hình ảnh, case study và bản dịch hay cần cùng làm rõ từ đầu.","Khả năng quản trị: nội dung có cần CMS, lịch xuất bản, nhiều người biên tập hoặc nhiều locale không.","Tích hợp và dữ liệu: form, CRM, email, thanh toán, bản đồ, analytics hoặc API bên thứ ba.","Mức trách nhiệm sau launch: SEO kỹ thuật, bảo mật, theo dõi lỗi, hướng dẫn bàn giao và các đợt cải tiến tiếp theo."]},{"type":"paragraph","text":"Các yếu tố này liên quan với nhau. Nội dung chưa rõ làm thay đổi cấu trúc trang; cấu trúc thay đổi làm thay đổi schema và SEO; CMS và tích hợp làm thay đổi cách kiểm thử; còn yêu cầu bàn giao quyết định phần tài liệu và quyền truy cập cần chuẩn bị. Tách từng hạng mục thành một con số nhỏ có thể làm báo giá trông rẻ hơn, nhưng không làm tổng công việc nhỏ đi."},{"type":"quote","text":"Chi phí hợp lý không phải là mức thấp nhất. Đó là mức phản ánh đúng phạm vi mà doanh nghiệp thực sự cần vận hành."},{"type":"heading","text":"Cách bắt đầu với một phiên bản đầu tiên vừa đủ"},{"type":"paragraph","text":"Với SME, phiên bản đầu tiên thường nên tập trung vào một đường đi rõ: khách hiểu bạn cung cấp gì, tin tưởng qua bằng chứng, rồi gửi yêu cầu hoặc thực hiện hành động tiếp theo. Những phần chưa có dữ liệu để quyết định có thể để phía sau một cấu trúc mở rộng, thay vì xây sẵn mọi tính năng. Khi nhu cầu đã được kiểm chứng, website có thể tiến hóa thành CMS sâu hơn, portal nội bộ hoặc sản phẩm SaaS mà không phải vứt bỏ nền tảng ban đầu."},{"type":"cta","label":"Xem phạm vi dịch vụ và bảng giá","href":"/pricing"},{"type":"cta","label":"Trao đổi phạm vi website của bạn","href":"/contact"},{"type":"cta","label":"Xem case study LogiVN","href":"/work/logivn"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_sme_website_cost_estimate_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_sme_website_cost_estimate_r1', 'en', '{"title":"What actually changes the cost of an SME website","eyebrow":"SME websites","excerpt":"A useful website estimate does not start with a fixed price per page. It starts with the business goal, content readiness, editing needs and integrations the team must operate.","seoTitle":"SME website cost: what changes the estimate — TUNG","seoDescription":"A practical guide to SME website cost: scope, content, CMS, integrations, SEO, security and handover responsibilities.","body":[{"type":"heading","text":"A quote is a model of scope"},{"type":"paragraph","text":"An SME website should not be priced by page count alone. Two ten-page websites can have very different work behind them when one needs static content and a contact form while the other needs a CMS, multiple languages, roles, CRM integration or a lead workflow. A useful estimate explains which decisions create effort and risk instead of handing both sides a number they have to interpret."},{"type":"heading","text":"Five inputs that commonly change the estimate"},{"type":"list","items":["The job of the site: company story, lead generation, sales, recruitment or support for an operating workflow.","Content readiness: whether messaging, imagery, proof, case studies and translations already exist.","Editing needs: CMS, publishing workflow, multiple editors, structured data or multiple locales.","Data and integrations: forms, CRM, email, payments, maps, analytics or third-party APIs.","After-launch responsibility: technical SEO, security, error monitoring, handover training and continued improvements."]},{"type":"paragraph","text":"These inputs compound. Unclear content changes the information architecture; architecture changes metadata and SEO; CMS and integrations change the test plan; handover requirements change the documentation and access work. Breaking the estimate into tiny line items can make the number look smaller without making the delivery smaller."},{"type":"quote","text":"A fair cost is not the lowest number. It is the number that matches what the business needs to operate."},{"type":"heading","text":"Start with a first release that earns its next step"},{"type":"paragraph","text":"For many small businesses, the first release should make one path clear: understand the offer, see credible proof, then enquire or take the next action. Features without evidence can stay behind an extensible structure instead of being built prematurely. Once demand is clearer, the site can grow into a deeper CMS, internal portal or SaaS product without discarding its foundation."},{"type":"cta","label":"View service scope and pricing","href":"/pricing"},{"type":"cta","label":"Discuss your website scope","href":"/contact"},{"type":"cta","label":"See the LogiVN case study","href":"/work/logivn"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_sme_website_cost_estimate_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_sme_website_cost_estimate_r1', 'ja', '{"title":"中小企業サイトの費用を変えるのは、ページ数より範囲","eyebrow":"中小企業のWebサイト","excerpt":"Webサイトの見積もりは、ページ単価だけでは決まりません。事業の目的、コンテンツの準備状況、更新方法、必要な連携を整理することから始まります。","seoTitle":"中小企業サイトの費用を左右する要素 — TUNG","seoDescription":"中小企業向けWebサイトの費用を、範囲、コンテンツ、CMS、連携、SEO、引き継ぎから整理します。","body":[{"type":"heading","text":"見積もりは、必要な範囲を表すもの"},{"type":"paragraph","text":"同じ十ページのサイトでも、必要な仕事は大きく異なります。静的な紹介と問い合わせフォームだけでよい場合もあれば、CMS、多言語、権限、CRM連携、問い合わせ後の運用フローが必要な場合もあります。良い見積もりは、単一の数字ではなく、どの判断が工数とリスクを生むかを説明します。"},{"type":"heading","text":"費用を変えやすい五つの入力"},{"type":"list","items":["サイトの役割：会社紹介、問い合わせ獲得、販売、採用、業務フローの支援。","コンテンツの準備：メッセージ、画像、実績、事例、翻訳が揃っているか。","更新方法：CMS、公開フロー、複数編集者、構造化データ、多言語が必要か。","データと連携：フォーム、CRM、メール、決済、地図、分析、外部API。","公開後の責任：テクニカルSEO、セキュリティ、監視、引き継ぎ、継続改善。"]},{"type":"paragraph","text":"これらは連鎖します。内容が曖昧なら情報設計が変わり、情報設計が変わればSEOと構造化データも変わります。CMSや連携が入ればテスト範囲が増え、引き継ぎには権限とドキュメントが必要です。項目を細かく分けても、実際の範囲が小さくなるわけではありません。"},{"type":"quote","text":"妥当な費用とは、最も安い数字ではなく、事業が運用する範囲に合った数字です。"},{"type":"heading","text":"最初のリリースを、次の判断につなげる"},{"type":"paragraph","text":"中小企業の最初のリリースでは、提供内容を理解し、根拠を確認し、問い合わせや次の行動へ進める道を明確にします。根拠のない機能は先に作り込まず、後から広げられる構造に留めます。需要が見えれば、CMS、社内ポータル、SaaSへと基盤を活かして拡張できます。"},{"type":"cta","label":"サービス範囲と料金を見る","href":"/pricing"},{"type":"cta","label":"サイトの範囲を相談する","href":"/contact"},{"type":"cta","label":"LogiVNのケーススタディを見る","href":"/work/logivn"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_sme_website_cost_estimate_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_sme_website_cost_estimate_r1', 'zh', '{"title":"中小企业网站的成本，取决于范围而非页数","eyebrow":"中小企业网站","excerpt":"可靠的网站估算不从固定的单页价格开始，而从业务目标、内容准备度、更新方式和团队必须运营的集成开始。","seoTitle":"中小企业网站成本由哪些因素决定 — TUNG","seoDescription":"从范围、内容、CMS、集成、SEO、安全与交接责任，理解中小企业网站成本估算。","body":[{"type":"heading","text":"报价是范围的模型"},{"type":"paragraph","text":"两个同样十页的网站，背后的工作可能完全不同。一个只需要静态内容和联系表单，另一个可能需要CMS、多语言、角色权限、CRM集成或线索处理流程。可靠的估算应说明哪些判断带来工作量和风险，而不是只给出一个需要双方猜测的数字。"},{"type":"heading","text":"五个常见的成本变量"},{"type":"list","items":["网站任务：企业介绍、获取线索、销售、招聘，或支持某个运营流程。","内容准备度：信息、图片、证明、案例和翻译是否已经可用。","更新方式：CMS、发布流程、多编辑者、结构化数据或多语言。","数据与集成：表单、CRM、邮件、支付、地图、分析或第三方API。","上线后责任：技术SEO、安全、错误监控、交接培训和持续改进。"]},{"type":"paragraph","text":"这些变量会互相影响。内容不清会改变信息架构；架构会改变SEO与元数据；CMS和集成会扩大测试范围；交接要求会带来文档和权限工作。把项目拆成很多小项，可能让数字看起来更低，却不会让交付范围变小。"},{"type":"quote","text":"合理的成本不是最低的数字，而是与企业真正需要运营的范围相匹配。"},{"type":"heading","text":"让首个版本赢得下一步判断"},{"type":"paragraph","text":"对很多中小企业来说，首个版本应先让一条路径清晰：理解服务、看到可信证明，然后咨询或采取下一步行动。没有证据支持的功能可以先放在可扩展结构之后，不必提前堆满。需求更明确后，网站可以成长为更深的CMS、内部门户或SaaS，而不必丢掉初始基础。"},{"type":"cta","label":"查看服务范围与价格","href":"/pricing"},{"type":"cta","label":"讨论你的网站范围","href":"/contact"},{"type":"cta","label":"查看 LogiVN 案例","href":"/work/logivn"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_sme_website_cost_estimate_r1');
