-- post/landing-business-website-or-saas
INSERT OR IGNORE INTO content_items (id, type, slug, status, sort_order, cover_media_id, meta_json, version, current_published_revision_id, created_at, updated_at, deleted_at) VALUES ('seed_post_landing_business_website_or_saas', 'post', 'landing-business-website-or-saas', 'published', 110, 'seed_media_blog_ai_workflow_system', '{"series":"service-guides","surface":"blog","status":"live","featured":false,"intent":"service-fit","coverAltVi":"Từ landing page đến sản phẩm SaaS: bản đồ quyết định phạm vi","coverAltEn":"A scope decision map from landing page to SaaS product","coverAltJa":"ランディングページからSaaSまでの範囲判断マップ","coverAltZh":"从落地页到 SaaS 的范围决策地图"}', 1, 'seed_post_landing_business_website_or_saas_r1', '2026-07-29T00:00:00.000Z', '2026-07-29T00:00:00.000Z', NULL);
INSERT OR IGNORE INTO revisions (id, content_item_id, version, status, data_json, created_by, created_at, published_at, slug, sort_order, cover_media_id) SELECT 'seed_post_landing_business_website_or_saas_r1', 'seed_post_landing_business_website_or_saas', 1, 'published', '{"series":"service-guides","surface":"blog","status":"live","featured":false,"intent":"service-fit","coverAltVi":"Từ landing page đến sản phẩm SaaS: bản đồ quyết định phạm vi","coverAltEn":"A scope decision map from landing page to SaaS product","coverAltJa":"ランディングページからSaaSまでの範囲判断マップ","coverAltZh":"从落地页到 SaaS 的范围决策地图"}', 'seed:buyer-intent:2026-07-29:v1', '2026-07-29T00:00:00.000Z', '2026-07-29T00:00:00.000Z', 'landing-business-website-or-saas', 110, 'seed_media_blog_ai_workflow_system' WHERE EXISTS (SELECT 1 FROM content_items WHERE id = 'seed_post_landing_business_website_or_saas');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_landing_business_website_or_saas_r1', 'vi', '{"title":"Landing page, website doanh nghiệp hay SaaS?","eyebrow":"Chọn đúng phạm vi sản phẩm","excerpt":"Ba loại dự án này không chỉ khác nhau ở số màn hình. Chúng khác ở mục tiêu, vòng đời dữ liệu, trách nhiệm vận hành và mức độ thay đổi mà đội ngũ cần kiểm soát.","seoTitle":"Landing page, website doanh nghiệp hay SaaS? — TUNG","seoDescription":"So sánh landing page, website doanh nghiệp và SaaS để chọn đúng phạm vi frontend, CMS, backend, dữ liệu và vận hành.","body":[{"type":"heading","text":"Đừng chọn loại dự án bằng tên gọi"},{"type":"paragraph","text":"Landing page, website doanh nghiệp và SaaS thường bị đặt cạnh nhau như ba gói tăng dần về số trang. Cách nhìn đó bỏ qua điều quan trọng hơn: người dùng cần làm gì, dữ liệu có thay đổi hay không, ai chịu trách nhiệm sau khi gửi form, và hệ thống có phải bảo vệ trạng thái của nhiều người dùng không. Một landing page tốt có thể khó ở nội dung và tốc độ; một SaaS nhỏ có thể bắt đầu ít màn hình nhưng đòi hỏi backend, quyền hạn và kiểm thử nghiêm túc."},{"type":"heading","text":"Khi landing page là lựa chọn đúng"},{"type":"paragraph","text":"Landing page phù hợp khi mục tiêu là tập trung một thông điệp, một chiến dịch hoặc một hành động chuyển đổi. Nó cần hierarchy rõ, nội dung có bằng chứng, responsive tốt, tốc độ và đo lường cơ bản. Không nên thêm đăng nhập, dashboard hay CMS phức tạp chỉ vì chúng nghe có vẻ chuyên nghiệp nếu đội ngũ chưa có quy trình cần dùng chúng."},{"type":"heading","text":"Khi cần website doanh nghiệp"},{"type":"paragraph","text":"Website doanh nghiệp phù hợp khi khách hàng cần hiểu đầy đủ về năng lực, dịch vụ, case study, đội ngũ và cách liên hệ. Phạm vi thường xoay quanh kiến trúc thông tin, hệ thống nội dung, SEO, biểu mẫu lead và khả năng để người không kỹ thuật tự cập nhật. Đây là một sản phẩm nội dung có vòng đời, không chỉ là một poster dài trên web."},{"type":"heading","text":"Khi bài toán đã là SaaS"},{"type":"paragraph","text":"SaaS bắt đầu khi nhiều người dùng cần đăng nhập, làm việc trên dữ liệu riêng, chia sẻ trạng thái hoặc trả tiền cho một quy trình lặp lại. Khi đó cần nghĩ về tenant, phân quyền, trạng thái, audit, bảo mật, tích hợp và vận hành production. Có thể khởi đầu từ một luồng rất nhỏ, nhưng không nên gọi đó là SaaS nếu phần backend chưa chịu trách nhiệm cho những điều người dùng tin là thật."},{"type":"quote","text":"Chọn phạm vi nhỏ không có nghĩa là chọn một sản phẩm nông. Nó có nghĩa là chọn đúng vòng lặp cần làm cho chắc trước."},{"type":"cta","label":"Xem các gói dịch vụ và phạm vi","href":"/pricing"},{"type":"cta","label":"Trao đổi để chọn hướng phù hợp","href":"/contact"},{"type":"cta","label":"Xem case study Fball.vn","href":"/work/fball"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_landing_business_website_or_saas_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_landing_business_website_or_saas_r1', 'en', '{"title":"Landing page, business website or SaaS?","eyebrow":"Choosing the right product scope","excerpt":"These project types differ by more than screen count. They differ by purpose, data lifecycle, operational responsibility and how much change the team must control.","seoTitle":"Landing page, business website or SaaS? — TUNG","seoDescription":"Compare landing pages, business websites and SaaS products to choose the right frontend, CMS, backend, data and operations scope.","body":[{"type":"heading","text":"Do not choose a project by its label"},{"type":"paragraph","text":"Landing pages, business websites and SaaS products are often presented as packages that simply grow in page count. The more useful question is what users must do, whether data changes, who handles the next step after a form submission and whether the system must protect shared state across users. A strong landing page can be difficult because of content and speed. A small SaaS can have few screens and still require serious backend, permissions and testing."},{"type":"heading","text":"When a landing page is the right scope"},{"type":"paragraph","text":"A landing page fits one message, campaign or conversion action. It needs clear hierarchy, credible proof, responsive behavior, speed and basic measurement. There is no reason to add login, dashboards or a complex CMS simply because those features sound professional when the team has no workflow that needs them yet."},{"type":"heading","text":"When a business website is the right scope"},{"type":"paragraph","text":"A business website fits when people need to understand the offer, services, proof, team and next contact step. The work usually centers on information architecture, an editable content system, SEO, lead forms and a way for non-technical owners to make updates. It is a living content product, not a long poster on the web."},{"type":"heading","text":"When the problem has become SaaS"},{"type":"paragraph","text":"The problem becomes SaaS when people need accounts, private data, shared state or a repeatable workflow they may pay to use. That introduces tenants, permissions, state transitions, audit, security, integrations and production operations. The first release can be narrow, but it should not promise SaaS behavior before the backend can protect what users believe to be true."},{"type":"quote","text":"A small scope is not a shallow product. It is the smallest loop that deserves to become reliable first."},{"type":"cta","label":"View service packages and scope","href":"/pricing"},{"type":"cta","label":"Discuss the right direction","href":"/contact"},{"type":"cta","label":"See the Fball.vn case study","href":"/work/fball"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_landing_business_website_or_saas_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_landing_business_website_or_saas_r1', 'ja', '{"title":"ランディングページ、企業サイト、それともSaaS？","eyebrow":"適切な範囲を選ぶ","excerpt":"三つの違いは画面数だけではありません。目的、データのライフサイクル、運用責任、チームが制御すべき変更が異なります。","seoTitle":"ランディングページ、企業サイト、SaaSの違い — TUNG","seoDescription":"ランディングページ、企業サイト、SaaSを比較し、フロントエンド、CMS、バックエンド、運用の範囲を考えます。","body":[{"type":"heading","text":"名前だけでプロジェクトを選ばない"},{"type":"paragraph","text":"ランディングページ、企業サイト、SaaSは、ページ数が増える順のパッケージとして扱われがちです。重要なのは、利用者が何をするか、データが変化するか、フォーム送信後の対応者は誰か、複数の利用者が共有状態を扱うかです。ランディングページは内容と速度が難しく、小さなSaaSは画面が少なくても権限、バックエンド、テストが必要になります。"},{"type":"heading","text":"ランディングページが合うとき"},{"type":"paragraph","text":"一つのメッセージ、キャンペーン、コンバージョンに集中するならランディングページが合います。情報の階層、根拠、レスポンシブ対応、速度、基本的な計測が重要です。まだ必要な業務フローがないのに、ログインやダッシュボード、複雑なCMSを加える必要はありません。"},{"type":"heading","text":"企業サイトが合うとき"},{"type":"paragraph","text":"提供内容、サービス、実績、チーム、問い合わせ方法を十分に伝える必要があるなら企業サイトです。情報設計、編集できるコンテンツ、SEO、問い合わせフォーム、非技術者が更新できる仕組みが中心になります。Web上の長いポスターではなく、更新されるコンテンツプロダクトです。"},{"type":"heading","text":"SaaSになったとき"},{"type":"paragraph","text":"アカウント、非公開データ、共有状態、継続して使うワークフローが必要になると、問題はSaaSになります。テナント、権限、状態遷移、監査、セキュリティ、連携、production運用が必要です。最初のリリースは小さくてよいですが、バックエンドがユーザーの期待する事実を守れる前にSaaSとして約束しないことが大切です。"},{"type":"quote","text":"小さな範囲とは浅い製品ではなく、まず信頼できる最小のループを選ぶことです。"},{"type":"cta","label":"サービス範囲と料金を見る","href":"/pricing"},{"type":"cta","label":"方向性を相談する","href":"/contact"},{"type":"cta","label":"Fball.vnのケーススタディを見る","href":"/work/fball"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_landing_business_website_or_saas_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_landing_business_website_or_saas_r1', 'zh', '{"title":"落地页、企业网站，还是 SaaS？","eyebrow":"选择合适的产品范围","excerpt":"三者的差异不只是页面数量，还包括目标、数据生命周期、运营责任，以及团队需要控制的变化范围。","seoTitle":"落地页、企业网站与 SaaS 如何选择 — TUNG","seoDescription":"比较落地页、企业网站和 SaaS，选择合适的前端、CMS、后端、数据与运营范围。","body":[{"type":"heading","text":"不要只按名称选择项目"},{"type":"paragraph","text":"落地页、企业网站和 SaaS 常被当作页面数量逐步增加的套餐。更重要的问题是：用户要完成什么，数据是否变化，表单提交后谁负责下一步，以及系统是否要保护多个用户共享的状态。一个优秀的落地页可能难在内容与速度；一个小型 SaaS 页面不多，却仍需要严肃的后端、权限与测试。"},{"type":"heading","text":"什么时候适合落地页"},{"type":"paragraph","text":"如果目标是聚焦一个信息、活动或转化动作，落地页就足够。它需要清晰层级、可信证明、响应式表现、速度和基础测量。如果团队还没有需要登录、仪表盘或复杂CMS的工作流，就不必因为这些功能听起来专业而提前加入。"},{"type":"heading","text":"什么时候需要企业网站"},{"type":"paragraph","text":"当访客需要完整了解服务、能力、案例、团队和联系方式时，企业网站更合适。重点通常是信息架构、可编辑内容、SEO、线索表单，以及让非技术人员能够更新内容。它是持续维护的内容产品，而不是一张很长的网页海报。"},{"type":"heading","text":"什么时候问题已经是 SaaS"},{"type":"paragraph","text":"当用户需要账户、私有数据、共享状态或反复使用并可能付费的流程时，问题就进入 SaaS。此时需要租户、权限、状态转换、审计、安全、集成与生产运营。首个版本可以很小，但后端应先保护用户认为真实的状态，再承诺 SaaS 行为。"},{"type":"quote","text":"小范围不是浅产品，而是先让最小的关键循环可靠。"},{"type":"cta","label":"查看服务套餐与范围","href":"/pricing"},{"type":"cta","label":"讨论适合的方向","href":"/contact"},{"type":"cta","label":"查看 Fball.vn 案例","href":"/work/fball"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_landing_business_website_or_saas_r1');
