INSERT OR IGNORE INTO revisions (id, content_item_id, version, status, data_json, created_by, created_at, published_at, slug, sort_order, cover_media_id) SELECT 'seed_post_website_handover_maintenance_seo_geo_r1', 'seed_post_website_handover_maintenance_seo_geo', 1, 'published', '{"series":"service-guides","surface":"blog","status":"live","featured":false,"intent":"handover","coverAltVi":"Checklist bàn giao website về quyền truy cập, SEO, bảo mật và vận hành","coverAltEn":"Website handover checklist for access, SEO, security and operations","coverAltJa":"権限、SEO、セキュリティ、運用を含むWebサイト引き継ぎチェックリスト","coverAltZh":"包含权限、SEO、安全与运营的网站交接清单"}', 'seed:buyer-intent:2026-07-29:v1', '2026-07-29T00:00:00.000Z', '2026-07-29T00:00:00.000Z', 'website-handover-maintenance-seo-geo', 120, 'seed_media_blog_tenant_boundary_product' WHERE EXISTS (SELECT 1 FROM content_items WHERE id = 'seed_post_website_handover_maintenance_seo_geo');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_website_handover_maintenance_seo_geo_r1', 'vi', '{"title":"Bàn giao website không kết thúc ở lúc deploy","eyebrow":"Bảo trì, bảo mật và SEO-GEO","excerpt":"Một website chỉ thực sự sẵn sàng khi doanh nghiệp biết ai sở hữu quyền truy cập, cách cập nhật nội dung, theo dõi SEO-GEO và xử lý sự cố sau ngày ra mắt.","seoTitle":"Bàn giao website: bảo trì, bảo mật và SEO-GEO — TUNG","seoDescription":"Checklist bàn giao website cho SME: quyền truy cập, backup, bảo mật, SEO-GEO, analytics, nội dung và quy trình xử lý sự cố.","body":[{"type":"heading","text":"Deploy chỉ là một mốc, không phải điểm kết thúc"},{"type":"paragraph","text":"Ngày website lên production thường được xem là ngày hoàn thành. Nhưng một doanh nghiệp vẫn cần biết ai có quyền quản trị domain, hosting, analytics, CMS, email gửi form và các tài khoản tích hợp. Nếu những quyền đó nằm trong một tài khoản cá nhân hoặc không có danh sách rõ ràng, website có thể chạy tốt hôm nay nhưng khó bảo vệ và tiếp tục phát triển ngày mai."},{"type":"heading","text":"Một gói bàn giao nên trả lời được những câu hỏi nào"},{"type":"list","items":["Ai sở hữu domain, Cloudflare hoặc hosting, DNS, email giao dịch và các tài khoản analytics.","Nội dung nào doanh nghiệp tự cập nhật được, nội dung nào cần người triển khai hỗ trợ.","Backup, log, cảnh báo lỗi và quy trình khôi phục nằm ở đâu; ai được phép thực hiện.","Canonical, sitemap, robots, schema, dữ liệu địa điểm và thông tin liên hệ được kiểm tra như thế nào.","Khi có sự cố hoặc thay đổi lớn, liên hệ ai, thời gian phản hồi kỳ vọng là gì, và quyết định nào cần phê duyệt."]},{"type":"heading","text":"SEO và GEO cần nền tảng vận hành, không chỉ metadata"},{"type":"paragraph","text":"SEO kỹ thuật giúp công cụ tìm kiếm đọc đúng cấu trúc. GEO ở đây là việc làm cho doanh nghiệp dễ được hiểu trong ngữ cảnh địa phương: dịch vụ, khu vực phục vụ, ngôn ngữ, bằng chứng và thông tin liên hệ cần nhất quán. Các tín hiệu này không thay thế nội dung tốt hay lời hứa về thứ hạng. Chúng giúp trang phản ánh đúng doanh nghiệp và giúp đội ngũ có thể tiếp tục cập nhật khi thông tin thay đổi."},{"type":"quote","text":"Bàn giao tốt là khi doanh nghiệp không cần gọi người xây website chỉ để biết website đang thuộc về ai."},{"type":"heading","text":"Bảo trì nên bắt đầu từ trách nhiệm rõ ràng"},{"type":"paragraph","text":"Không phải website nào cũng cần một gói vận hành lớn. Điều cần trước tiên là biết những gì phải theo dõi: domain và chứng chỉ, biểu mẫu, lỗi runtime, dependency, tài khoản truy cập, nội dung quan trọng và tín hiệu tìm kiếm. Từ đó mới quyết định phần nào doanh nghiệp tự làm, phần nào cần hỗ trợ định kỳ. Cách này minh bạch hơn việc bán một gói bảo trì chung nhưng không nói rõ nó bảo vệ điều gì."},{"type":"cta","label":"Xem phạm vi dịch vụ và bảng giá","href":"/pricing"},{"type":"cta","label":"Trao đổi kế hoạch bàn giao","href":"/contact"},{"type":"cta","label":"Xem case study hạ tầng thanh toán","href":"/work/payment-infrastructure"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_website_handover_maintenance_seo_geo_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_website_handover_maintenance_seo_geo_r1', 'en', '{"title":"Website handover does not end at deploy","eyebrow":"Maintenance, security and SEO-GEO","excerpt":"A website is ready when the business knows who owns access, how content changes, how SEO-GEO is monitored and what happens when something breaks after launch.","seoTitle":"Website handover: maintenance, security and SEO-GEO — TUNG","seoDescription":"A practical SME website handover checklist covering access, backups, security, SEO-GEO, analytics, content and incident ownership.","body":[{"type":"heading","text":"Deploy is a milestone, not the finish line"},{"type":"paragraph","text":"The production release is often treated as the day a website is complete. The business still needs to know who owns the domain, Cloudflare or hosting, analytics, CMS, form email and integration accounts. If those permissions live in one personal account or no inventory exists, the site may run today while becoming difficult to protect and extend tomorrow."},{"type":"heading","text":"What a useful handover should answer"},{"type":"list","items":["Who owns the domain, Cloudflare or hosting, DNS, transactional email and analytics accounts.","Which content the business can update itself and which changes need implementation support.","Where backups, logs, error alerts and recovery steps live, and who may use them.","How canonical URLs, sitemap, robots, schema, location data and contact details are checked.","Who to contact after an incident or major change, expected response time and decisions that need approval."]},{"type":"heading","text":"SEO and GEO need an operating foundation, not only metadata"},{"type":"paragraph","text":"Technical SEO helps crawlers read the structure correctly. GEO here means making the business understandable in its local context: service, coverage area, language, proof and contact details should agree across the site. These signals do not replace useful content or promise rankings. They make the site more faithful to the business and easier for the team to maintain when facts change."},{"type":"quote","text":"A good handover means the business does not need to call the builder just to find out who owns the website."},{"type":"heading","text":"Maintenance starts with clear responsibility"},{"type":"paragraph","text":"Not every website needs a large operations retainer. First identify what must be watched: domain and certificates, forms, runtime errors, dependencies, access accounts, important content and search signals. Then decide which parts the business owns and which parts need periodic help. That is more honest than selling a generic maintenance package without saying what it protects."},{"type":"cta","label":"View service scope and pricing","href":"/pricing"},{"type":"cta","label":"Discuss your handover plan","href":"/contact"},{"type":"cta","label":"See the payment infrastructure case study","href":"/work/payment-infrastructure"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_website_handover_maintenance_seo_geo_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_website_handover_maintenance_seo_geo_r1', 'ja', '{"title":"Webサイトの引き継ぎはデプロイで終わらない","eyebrow":"保守、セキュリティ、SEO-GEO","excerpt":"サイトは公開したら終わりではありません。権限の所有者、更新方法、SEO-GEOの確認、公開後の障害対応を事業側が理解できて初めて運用できます。","seoTitle":"Webサイト引き継ぎと保守・SEO-GEO — TUNG","seoDescription":"中小企業サイトの引き継ぎを、権限、バックアップ、セキュリティ、SEO-GEO、分析、障害対応から整理します。","body":[{"type":"heading","text":"デプロイは節目であり、終点ではない"},{"type":"paragraph","text":"production公開の日を完成日と考えがちですが、事業側には確認すべきことが残ります。ドメイン、Cloudflareやホスティング、分析、CMS、フォームの送信先、連携アカウントを誰が所有するのか。個人アカウントだけに権限が集まり、一覧もなければ、今日動いていても明日から守り、広げることが難しくなります。"},{"type":"heading","text":"引き継ぎで答えられるべき質問"},{"type":"list","items":["ドメイン、Cloudflareやホスティング、DNS、通知メール、分析アカウントの所有者は誰か。","事業側で更新できる内容と、実装支援が必要な変更は何か。","バックアップ、ログ、エラー通知、復旧手順はどこにあり、誰が使えるか。","canonical、sitemap、robots、schema、地域情報、連絡先をどう確認するか。","障害や大きな変更の連絡先、対応時間の目安、承認が必要な判断は何か。"]},{"type":"heading","text":"SEOとGEOはメタデータだけでは続かない"},{"type":"paragraph","text":"テクニカルSEOはクローラーが構造を正しく読むための基盤です。ここでいうGEOは、サービス、対応地域、言語、実績、連絡先を地域の文脈で一貫して伝えることです。これらは順位を保証するものではありません。事業の事実を正しく表し、変更後もチームが更新できる仕組みを作ります。"},{"type":"quote","text":"良い引き継ぎとは、誰がサイトを所有しているかを知るために、毎回制作者へ連絡しなくてよい状態です。"},{"type":"heading","text":"保守は責任の境界から始まる"},{"type":"paragraph","text":"すべてのサイトに大きな運用契約が必要なわけではありません。まず、ドメインと証明書、フォーム、runtimeエラー、依存関係、権限、重要コンテンツ、検索シグナルの何を確認するか決めます。その後、事業側で担う部分と定期支援が必要な部分を分けます。守る対象を説明しない一律の保守パッケージより、透明な運用です。"},{"type":"cta","label":"サービス範囲と料金を見る","href":"/pricing"},{"type":"cta","label":"引き継ぎ計画を相談する","href":"/contact"},{"type":"cta","label":"決済インフラのケーススタディを見る","href":"/work/payment-infrastructure"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_website_handover_maintenance_seo_geo_r1');
INSERT OR IGNORE INTO localizations (revision_id, locale, data_json) SELECT 'seed_post_website_handover_maintenance_seo_geo_r1', 'zh', '{"title":"网站交接不会在部署时结束","eyebrow":"维护、安全与 SEO-GEO","excerpt":"网站真正准备好，是企业知道谁拥有访问权、如何更新内容、如何检查 SEO-GEO，以及上线后出现问题由谁处理。","seoTitle":"网站交接：维护、安全与 SEO-GEO — TUNG","seoDescription":"中小企业网站交接清单：访问权、备份、安全、SEO-GEO、分析、内容和故障责任。","body":[{"type":"heading","text":"部署是里程碑，不是终点"},{"type":"paragraph","text":"生产环境发布常被当作网站完成的那一天，但企业仍需知道域名、Cloudflare或主机、分析、CMS、表单邮箱和集成账户由谁拥有。如果权限集中在一个个人账户中，或根本没有清单，网站也许今天能运行，明天却难以保护和扩展。"},{"type":"heading","text":"一份有用的交接应回答什么"},{"type":"list","items":["域名、Cloudflare或主机、DNS、交易邮件与分析账户的所有者是谁。","哪些内容企业可以自行更新，哪些变更需要实施支持。","备份、日志、错误提醒和恢复步骤在哪里，谁可以使用。","如何检查canonical、sitemap、robots、schema、地域信息和联系方式。","发生故障或重大变更后联系谁、响应时间预期是什么、哪些决定需要批准。"]},{"type":"heading","text":"SEO 与 GEO 需要运营基础，而不只是元数据"},{"type":"paragraph","text":"技术SEO帮助爬虫正确读取结构。这里的GEO是让企业在本地语境中容易被理解：服务、覆盖区域、语言、证明和联系方式应在网站中保持一致。这些信号不替代有用内容，也不承诺排名；它们让网站更准确地反映企业，并让团队能在事实变化后继续维护。"},{"type":"quote","text":"好的交接，是企业不必每次想知道网站归谁所有，都去联系制作方。"},{"type":"heading","text":"维护从明确责任开始"},{"type":"paragraph","text":"并非每个网站都需要大型运维服务。先明确要监测什么：域名和证书、表单、运行时错误、依赖、访问账户、重要内容与搜索信号。再决定哪些由企业负责，哪些需要定期协助。这比销售一个不说明保护对象的通用维护套餐更透明。"},{"type":"cta","label":"查看服务范围与价格","href":"/pricing"},{"type":"cta","label":"讨论你的网站交接计划","href":"/contact"},{"type":"cta","label":"查看支付基础设施案例","href":"/work/payment-infrastructure"}]}' WHERE EXISTS (SELECT 1 FROM revisions WHERE id = 'seed_post_website_handover_maintenance_seo_geo_r1');
UPDATE content_items SET status = 'published', current_published_revision_id = 'seed_post_website_handover_maintenance_seo_geo_r1' WHERE id = 'seed_post_website_handover_maintenance_seo_geo' AND current_published_revision_id IS NULL AND status = 'published' AND version = 1 AND created_at = '2026-07-29T00:00:00.000Z' AND updated_at = '2026-07-29T00:00:00.000Z';
